(()=>{const controls=[...document.querySelectorAll('[data-marine-tool]')];if(!controls.length)return;function select(button){for(const control of controls){const open=control===button;control.setAttribute('aria-expanded',String(open));control.querySelector('b').textContent=open?'−':'+';document.getElementById(control.dataset.marineTool).hidden=!open}}controls.forEach((button,i)=>{button.addEventListener('click',()=>select(button));button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const index=event.key==='Home'?0:event.key==='End'?controls.length-1:(i+(event.key==='ArrowRight'?1:-1)+controls.length)%controls.length;controls[index].focus();select(controls[index])})})})();
